// Spring Boot concepts. Exercises model each framework mechanism in plain JDK code (Spring
// jars aren't available offline); Learn always shows the real Spring version from CometCarpool.
import { lesson, conceptLesson, program, checks } from './helpers.mjs';

const S = 'https://docs.spring.io/';
const REFLECT = 'import java.lang.annotation.*;\nimport java.lang.reflect.*;\nimport java.util.*;';
const HASH = 'import java.nio.charset.StandardCharsets;\nimport java.security.*;\nimport java.util.*;\nimport java.util.function.*;';
const JWT = 'import java.nio.charset.StandardCharsets;\nimport java.security.MessageDigest;\nimport java.util.*;\nimport javax.crypto.Mac;\nimport javax.crypto.spec.SecretKeySpec;';
const sha = 'static String sha256(String text) {\n    try {\n        byte[] digest = MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8));\n        return HexFormat.of().formatHex(digest);\n    } catch (NoSuchAlgorithmException e) {\n        throw new IllegalStateException(e);\n    }\n}';
const jwtHelpers = 'static String b64(String text) {\n    return Base64.getUrlEncoder().withoutPadding().encodeToString(text.getBytes(StandardCharsets.UTF_8));\n}\n\nstatic String unb64(String part) {\n    return new String(Base64.getUrlDecoder().decode(part), StandardCharsets.UTF_8);\n}\n\nstatic String sign(String data, String secret) {\n    try {\n        Mac mac = Mac.getInstance("HmacSHA256");\n        mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));\n        return Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(data.getBytes(StandardCharsets.UTF_8)));\n    } catch (Exception e) {\n        throw new IllegalStateException(e);\n    }\n}';
const field = '// Reads "key":value from our flat JSON payloads.\nstatic String field(String json, String key) {\n    var m = java.util.regex.Pattern.compile("\\"" + key + "\\":\\"?([^\\",}]*)").matcher(json);\n    return m.find() ? m.group(1) : null;\n}';
const svc = 'interface UserRepository {\n    boolean existsByEmail(String email);\n    void save(String email);\n}\n\nclass UserService {\n    final UserRepository repo;\n\n    UserService(UserRepository repo) {\n        this.repo = repo;\n    }\n\n    void register(String raw) {\n        if (raw == null || !raw.trim().toLowerCase().endsWith("@utdallas.edu")) {\n            throw new IllegalArgumentException("User must be a student with a UTD email address.");\n        }\n        String email = raw.trim().toLowerCase();\n        if (repo.existsByEmail(email)) {\n            throw new IllegalArgumentException("A user with this email already exists.");\n        }\n        repo.save(email);\n    }\n}\n\nclass MockRepo implements UserRepository {\n    boolean exists;\n    List<String> saved = new ArrayList<>();\n    public boolean existsByEmail(String email) { return exists; }\n    public void save(String email) { saved.add(email); }\n}';

